# Exact Z[r,a,v] arithmetic, with exponent tuples in order (r,a,v).
from math import comb
ZERO={}
ONE={(0,0,0):1}
R={(1,0,0):1}
A={(0,1,0):1}
V={(0,0,1):1}
def add(p,q):
    out=dict(p)
    for k,c in q.items():
        out[k]=out.get(k,0)+c
    return {k:c for k,c in out.items() if c}
def scale(c,p):
    return {k:c*x for k,x in p.items() if c*x}
def mul(p,q):
    out={}
    for e,c in p.items():
        for f,d in q.items():
            k=tuple(e[i]+f[i] for i in range(3))
            out[k]=out.get(k,0)+c*d
    return {k:c for k,c in out.items() if c}
def power(p,n):
    out=ONE
    for _ in range(n):
        out=mul(out,p)
    return out
def deriv(p):
    return {(k[0]-1,k[1],k[2]):c*k[0] for k,c in p.items() if k[0]}
def eval_at(p,r,a,v):
    return sum(c*r**k[0]*a**k[1]*v**k[2] for k,c in p.items())
def specialize(p,a,v):
    out={}
    for k,c in p.items():
        d=(k[0],0,0)
        out[d]=out.get(d,0)+c*a**k[1]*v**k[2]
    return {k:c for k,c in out.items() if c}
